-- Shushop database setup (tables only).
-- Supabase: open "SQL Editor", paste this whole file, press Run. Safe to run again: it starts by dropping Shushop's tables.
-- Generated by "npm run db:build-sql" from db/schema.sql. Do not edit by hand.

-- Start clean: removes only Shushop's own tables.
DROP VIEW IF EXISTS product_ratings;
DROP TABLE IF EXISTS notifications CASCADE;
DROP TABLE IF EXISTS order_status_log CASCADE;
DROP TABLE IF EXISTS order_items CASCADE;
DROP TABLE IF EXISTS orders CASCADE;
DROP TABLE IF EXISTS coupons CASCADE;
DROP TABLE IF EXISTS stock_alerts CASCADE;
DROP TABLE IF EXISTS cart_items CASCADE;
DROP TABLE IF EXISTS favourites CASCADE;
DROP TABLE IF EXISTS reviews CASCADE;
DROP TABLE IF EXISTS variants CASCADE;
DROP TABLE IF EXISTS products CASCADE;
DROP TABLE IF EXISTS brands CASCADE;
DROP TABLE IF EXISTS addresses CASCADE;
DROP TABLE IF EXISTS sessions CASCADE;
DROP TABLE IF EXISTS users CASCADE;

-- Shushop database schema (PostgreSQL 15+; works on Supabase).
-- Safe to run more than once: every statement uses IF NOT EXISTS / OR REPLACE, nothing is deleted.
-- Money is stored in so'm as whole numbers (BIGINT). Shoe sizes are EU sizes.

-- ---------------------------------------------------------------- accounts
CREATE TABLE IF NOT EXISTS users (
  id            INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  email         TEXT NOT NULL UNIQUE,
  password_hash TEXT NOT NULL,                       -- bcrypt hash, never the password itself
  full_name     TEXT NOT NULL CHECK (char_length(full_name) BETWEEN 2 AND 60),
  phone         TEXT,
  role          TEXT NOT NULL DEFAULT 'customer' CHECK (role IN ('customer', 'admin')),
  shoe_size_eu  SMALLINT CHECK (shoe_size_eu BETWEEN 16 AND 50),
  created_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS sessions (
  token_hash TEXT PRIMARY KEY,                       -- SHA-256 of the token; the token itself is never stored
  user_id    INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  expires_at TIMESTAMPTZ NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS sessions_user_idx ON sessions(user_id);

CREATE TABLE IF NOT EXISTS addresses (
  id         INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  user_id    INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  label      TEXT NOT NULL CHECK (char_length(label) BETWEEN 1 AND 30),   -- "Home", "Work"
  line       TEXT NOT NULL CHECK (char_length(line) BETWEEN 5 AND 200),    -- street, house, flat
  city       TEXT NOT NULL CHECK (char_length(city) BETWEEN 2 AND 60),
  phone      TEXT NOT NULL,
  is_default BOOLEAN NOT NULL DEFAULT false,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS addresses_user_idx ON addresses(user_id);

-- ---------------------------------------------------------------- catalogue
CREATE TABLE IF NOT EXISTS brands (
  id   INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  name TEXT NOT NULL UNIQUE
);

CREATE TABLE IF NOT EXISTS products (
  id          INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  brand_id    INTEGER NOT NULL REFERENCES brands(id),
  name        TEXT NOT NULL CHECK (char_length(name) BETWEEN 2 AND 80),
  type        TEXT NOT NULL DEFAULT 'Sneakers',                           -- "Sports", "Sneakers", "Boots"...
  category    TEXT NOT NULL CHECK (category IN ('men', 'women', 'kids', 'unisex')),
  description TEXT NOT NULL DEFAULT '',
  price       BIGINT NOT NULL CHECK (price > 0),
  old_price   BIGINT CHECK (old_price IS NULL OR old_price > price),     -- set = the shoe is on sale
  art_style   TEXT NOT NULL DEFAULT 'court' CHECK (art_style IN ('court', 'runner', 'high', 'chunky', 'slip', 'boot')),
  image_url   TEXT,                                                      -- optional real photo; otherwise generated art
  is_active   BOOLEAN NOT NULL DEFAULT true,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS products_brand_idx ON products(brand_id);
CREATE INDEX IF NOT EXISTS products_category_idx ON products(category) WHERE is_active;

-- One row per size + colour of a product. "stock" is what we can sell right now.
CREATE TABLE IF NOT EXISTS variants (
  id         INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  product_id INTEGER NOT NULL REFERENCES products(id) ON DELETE CASCADE,
  size       SMALLINT NOT NULL CHECK (size BETWEEN 16 AND 50),            -- EU size
  color_name TEXT NOT NULL,
  color_hex  TEXT NOT NULL CHECK (color_hex ~ '^#[0-9a-f]{6}$'),
  stock      INTEGER NOT NULL DEFAULT 0 CHECK (stock >= 0),               -- can never go below zero
  UNIQUE (product_id, size, color_name)
);
CREATE INDEX IF NOT EXISTS variants_product_idx ON variants(product_id);

CREATE TABLE IF NOT EXISTS reviews (
  id         INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  product_id INTEGER NOT NULL REFERENCES products(id) ON DELETE CASCADE,
  user_id    INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  rating     SMALLINT NOT NULL CHECK (rating BETWEEN 1 AND 5),
  comment    TEXT NOT NULL DEFAULT '' CHECK (char_length(comment) <= 500),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (product_id, user_id)                                            -- one review per person per shoe
);

-- Average rating and review count per product (a VIEW: always up to date, nothing to maintain)
CREATE OR REPLACE VIEW product_ratings WITH (security_invoker = true) AS
  SELECT product_id, count(*)::int AS review_count, round(avg(rating)::numeric, 1) AS avg_rating
    FROM reviews GROUP BY product_id;

-- ---------------------------------------------------------------- wishlist, cart, alerts
CREATE TABLE IF NOT EXISTS favourites (
  user_id    INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  product_id INTEGER NOT NULL REFERENCES products(id) ON DELETE CASCADE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (user_id, product_id)
);

CREATE TABLE IF NOT EXISTS cart_items (
  user_id    INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  variant_id INTEGER NOT NULL REFERENCES variants(id) ON DELETE CASCADE,
  qty        INTEGER NOT NULL CHECK (qty BETWEEN 1 AND 10),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (user_id, variant_id)
);

-- "Tell me when this shoe is back in stock"
CREATE TABLE IF NOT EXISTS stock_alerts (
  user_id    INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  product_id INTEGER NOT NULL REFERENCES products(id) ON DELETE CASCADE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (user_id, product_id)
);

CREATE TABLE IF NOT EXISTS coupons (
  code       TEXT PRIMARY KEY CHECK (code = upper(code)),
  percent    SMALLINT NOT NULL CHECK (percent BETWEEN 1 AND 90),
  min_total  BIGINT NOT NULL DEFAULT 0,
  active     BOOLEAN NOT NULL DEFAULT true,
  expires_at TIMESTAMPTZ
);

-- ---------------------------------------------------------------- orders
CREATE TABLE IF NOT EXISTS orders (
  id             INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  user_id        INTEGER NOT NULL REFERENCES users(id),
  status         TEXT NOT NULL DEFAULT 'new' CHECK (status IN ('new', 'processing', 'shipped', 'delivered', 'cancelled')),
  subtotal       BIGINT NOT NULL CHECK (subtotal >= 0),
  shipping_fee   BIGINT NOT NULL DEFAULT 0 CHECK (shipping_fee >= 0),
  discount       BIGINT NOT NULL DEFAULT 0 CHECK (discount >= 0),
  total          BIGINT NOT NULL CHECK (total >= 0),
  coupon_code    TEXT,
  address_line   TEXT NOT NULL,
  city           TEXT NOT NULL,
  phone          TEXT NOT NULL,
  payment_method TEXT NOT NULL CHECK (payment_method IN ('cash', 'card', 'payme', 'click')),
  created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at     TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS orders_user_idx ON orders(user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS orders_status_idx ON orders(status, created_at DESC);

-- Name, size, colour and PRICE are copied into the order, so later catalogue changes never rewrite history.
CREATE TABLE IF NOT EXISTS order_items (
  id           INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  order_id     INTEGER NOT NULL REFERENCES orders(id) ON DELETE CASCADE,
  variant_id   INTEGER REFERENCES variants(id) ON DELETE SET NULL,
  product_id   INTEGER REFERENCES products(id) ON DELETE SET NULL,
  product_name TEXT NOT NULL,
  brand_name   TEXT NOT NULL,
  size         SMALLINT NOT NULL,
  color_name   TEXT NOT NULL,
  color_hex    TEXT NOT NULL,
  art_style    TEXT NOT NULL DEFAULT 'court',
  unit_price   BIGINT NOT NULL CHECK (unit_price >= 0),
  qty          INTEGER NOT NULL CHECK (qty > 0)
);
CREATE INDEX IF NOT EXISTS order_items_order_idx ON order_items(order_id);

CREATE TABLE IF NOT EXISTS order_status_log (
  id         INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  order_id   INTEGER NOT NULL REFERENCES orders(id) ON DELETE CASCADE,
  status     TEXT NOT NULL,
  changed_by INTEGER REFERENCES users(id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS order_status_log_order_idx ON order_status_log(order_id, created_at);

-- ---------------------------------------------------------------- notifications
CREATE TABLE IF NOT EXISTS notifications (
  id         INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  user_id    INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  kind       TEXT NOT NULL CHECK (kind IN ('drop', 'restock', 'price_drop', 'order')),
  title      TEXT NOT NULL,
  body       TEXT NOT NULL,
  product_id INTEGER REFERENCES products(id) ON DELETE SET NULL,
  order_id   INTEGER REFERENCES orders(id) ON DELETE SET NULL,
  is_read    BOOLEAN NOT NULL DEFAULT false,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS notifications_user_idx ON notifications(user_id, created_at DESC);

-- ---------------------------------------------------------------- security
-- Supabase publishes every table in the "public" schema through an automatic REST API. Turning row-level
-- security ON (with no policies) makes that public API see nothing. Our server connects with the database
-- owner role, which is not affected, so the website and the Android app keep working normally.
ALTER TABLE users            ENABLE ROW LEVEL SECURITY;
ALTER TABLE sessions         ENABLE ROW LEVEL SECURITY;
ALTER TABLE addresses        ENABLE ROW LEVEL SECURITY;
ALTER TABLE brands           ENABLE ROW LEVEL SECURITY;
ALTER TABLE products         ENABLE ROW LEVEL SECURITY;
ALTER TABLE variants         ENABLE ROW LEVEL SECURITY;
ALTER TABLE reviews          ENABLE ROW LEVEL SECURITY;
ALTER TABLE favourites       ENABLE ROW LEVEL SECURITY;
ALTER TABLE cart_items       ENABLE ROW LEVEL SECURITY;
ALTER TABLE stock_alerts     ENABLE ROW LEVEL SECURITY;
ALTER TABLE coupons          ENABLE ROW LEVEL SECURITY;
ALTER TABLE orders           ENABLE ROW LEVEL SECURITY;
ALTER TABLE order_items      ENABLE ROW LEVEL SECURITY;
ALTER TABLE order_status_log ENABLE ROW LEVEL SECURITY;
ALTER TABLE notifications    ENABLE ROW LEVEL SECURITY;
